<?php\n\nnamespace App\Traits;\n\nuse App\Models\MetaTag;\nuse Illuminate\Database\Eloquent\Relations\MorphOne;\nuse Illuminate\Support\Str;\n\ntrait HasMetaTags\n{\n    /**\n     * Get the entity\'s meta tags.\n     */\n    public function metaTag(): MorphOne\n    {\n        return $this->morphOne(MetaTag::class, \'meta_taggable\');\n    }\n\n    /**\n     * Sync (create or update) the meta tags for the entity.\n     *\n     * @param array $data\n     * @return MetaTag\n     */\n    public function syncMetaTags(array $data): MetaTag\n    {\n        // Filter out keys that don\'t belong to the MetaTag model\n        $fillableMetaKeys = (new MetaTag())->getFillable();\n        $metaData = array_intersect_key($data, array_flip($fillableMetaKeys));\n\n        return $this->metaTag()->updateOrCreate(\n            [], // No unique identifier needed for updateOrCreate on a morphOne relationship\n            $metaData\n        );\n    }\n\n    /**\n     * Get the SEO title for the entity, with fallback.\n     */\n    public function getSeoTitle(): string\n    {\n        $meta = $this->metaTag;\n\n        // Use custom meta title if available\n        if ($meta && $meta->title) {\n            return $this->replaceDynamicPlaceholders($meta->title);\n        }\n\n        // Fallback to entity\'s name or title\n        if (isset($this->name)) {\n            return $this->replaceDynamicPlaceholders($this->name);\n        }\n        if (isset($this->title)) {\n            return $this->replaceDynamicPlaceholders($this->title);\n        }\n\n        return config(\'app.name\', \'Shopora\'); // Default application name\n    }\n\n    /**\n     * Get the SEO description for the entity, with fallback.\n     */\n    public function getSeoDescription(): string\n    {\n        $meta = $this->metaTag;\n\n        // Use custom meta description if available\n        if ($meta && $meta->description) {\n            return $this->replaceDynamicPlaceholders($meta->description);\n        }\n\n        // Fallback to entity\'s description or excerpt\n        if (isset($this->description)) {\n            return $this->replaceDynamicPlaceholders(Str::limit($this->description, 160));\n        }\n        if (isset($this->excerpt)) {\n            return $this->replaceDynamicPlaceholders(Str::limit($this->excerpt, 160));\n        }\n\n        return config(\'seo.default_description\', \'بهترین محصولات را از فروشگاه ما بخرید.\'); // Default global description\n    }\n\n    /**\n     * Get the SEO image for the entity, with fallback.\n     */\n    public function getSeoImage(): ?string\n    {\n        $meta = $this->metaTag;\n\n        // Use custom meta image if available\\n        if ($meta && $meta->og_image) {\n            return $this->replaceDynamicPlaceholders($meta->og_image);\n        }\n        if ($meta && $meta->twitter_image) {\n            return $this->replaceDynamicPlaceholders($meta->twitter_image);\n        }\n\n        // Fallback to entity\'s featured_image or image\n        if (isset($this->featured_image)) {\n            return $this->replaceDynamicPlaceholders($this->featured_image);\n        }\n        if (isset($this->image)) {\n            return $this->replaceDynamicPlaceholders($this->image);\n        }\n\n        return config(\'seo.default_image\', null); // Default global image\n    }\n\n    /**\n     * Get the canonical URL for the entity, with fallback.\n     */\n    public function getSeoCanonicalUrl(): string\n    {\n        $meta = $this->metaTag;\n\n        // Use custom canonical URL if available\n        if ($meta && $meta->canonical_url) {\n            return $this->replaceDynamicPlaceholders($meta->canonical_url);\n        }\n\n        // Fallback to entity\'s own URL if it has a getUrl method\n        if (method_exists($this, \'getUrl\')) {\n            return $this->getUrl();\n        }\n\n        return url()->current(); // Fallback to current URL\n    }\n\n    /**\n     * Get the robots meta tag for the entity, with fallback.\n     */\n    public function getSeoRobots(): string\n    {\n        $meta = $this->metaTag;\n\n        if ($meta && $meta->robots) {\n            return $this->replaceDynamicPlaceholders($meta->robots);\n        }\n\n        return config(\'seo.default_robots\', \'index, follow\'); // Default robots\n    }\n\n    /**\n     * Get the SEO keywords for the entity, with fallback.\n     */\n    public function getSeoKeywords(): string\n    {\n        $meta = $this->metaTag;\n\n        if ($meta && $meta->keywords) {\n            return $this->replaceDynamicPlaceholders($meta->keywords);\n        }\n\n        // Fallback to a comma-separated list of product/category tags or a default\n        // You might need to adjust \'tags\' relationship based on your actual model structure\n        if (isset($this->tags) && method_exists($this->tags, \'isNotEmpty\') && $this->tags->isNotEmpty()) {\n            return $this->replaceDynamicPlaceholders($this->tags->pluck(\'name\')->implode(\', \'));\n        }\n\n        return config(\'seo.default_keywords\', \'\');\n    }\n\n    /**\n     * Replace dynamic placeholders in a string.\n     * This method can be extended to support more complex placeholders.\n     */\n    protected function replaceDynamicPlaceholders(string $value): string\n    {\n        // Example: Replace {name} with the entity\'s name\n        $value = Str::replace(\'{name}\', $this->name ?? \'\', $value);\n        $value = Str::replace(\'{title}\', $this->title ?? \'\', $value);\n        $value = Str::replace(\'{description}\', $this->description ?? \'\', $value);\n        $value = Str::replace(\'{app_name}\', config(\'app.name\', \'Shopora\'), $value);\n        // Add more placeholders as needed\n\n        return $value;\n    }\n}\n
